<?php require_once __DIR__ . '/auth.php'; require_login('admin');$subjects=many('SELECT s.name,COUNT(qa.id) attempts,ROUND(AVG(qa.accuracy)) accuracy FROM subjects s LEFT JOIN quiz_attempts qa ON qa.subject_id=s.id GROUP BY s.id ORDER BY accuracy DESC');$weak=many('SELECT s.name,ROUND(AVG(qa.accuracy)) accuracy FROM subjects s JOIN quiz_attempts qa ON qa.subject_id=s.id GROUP BY s.id ORDER BY accuracy LIMIT 3');$pageTitle='Admin analytics';include 'includes/header.php';?><div class="page-head"><div><div class="eyebrow">Network intelligence</div><h1>Analytics.</h1><p>See the subjects and topics that need a better nudge.</p></div></div><div class="dashboard-grid"><section class="panel"><div class="panel-head"><h2>Subject performance</h2><small>All students</small></div><?php foreach($subjects as $item):?><div class="skill-row"><div class="skill-label"><strong><?=e($item['name'])?></strong><span><?=$item['attempts']?> attempts · <?=$item['accuracy']??0?>%</span></div><div class="progress"><i data-progress="<?=round($item['accuracy']??0)?>"></i></div></div><?php endforeach;?></section><section class="panel"><div class="eyebrow">Weak areas</div><h2>Where to intervene.</h2><?php foreach($weak as $item):?><div class="achievement"><span style="background:#ffe8e1;color:#a64123">!</span><div><strong><?=e($item['name'])?></strong><small><?=$item['accuracy']?>% network accuracy</small></div></div><?php endforeach;?></section></div><?php include 'includes/footer.php';?>